// ValidateRegisterIssuerRequestBody runs the validations defined on
// RegisterIssuerRequestBody
func ValidateRegisterIssuerRequestBody(body *RegisterIssuerRequestBody) (err error) {
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Issuer == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("issuer", "body"))
	}
	if body.JwksURI == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("jwks_uri", "body"))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 100 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 100, false))
		}
	}
	if body.Issuer != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.issuer", *body.Issuer, goa.FormatURI))
	}
	if body.JwksURI != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.jwks_uri", *body.JwksURI, goa.FormatURI))
	}
	return
}

// ValidateAdmitSubjectRequestBody runs the validations defined on
// AdmitSubjectRequestBody
func ValidateAdmitSubjectRequestBody(body *AdmitSubjectRequestBody) (err error) {
	if body.Issuer == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("issuer", "body"))
	}
	if body.Subject == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("subject", "body"))
	}
	if body.AgentID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("agent_id", "body"))
	}
	if body.Issuer != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.issuer", *body.Issuer, goa.FormatURI))
	}
	if body.MatchKind != nil {
		if !(*body.MatchKind == "exact" || *body.MatchKind == "wildcard") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.match_kind", *body.MatchKind, []any{"exact", "wildcard"}))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.AgentID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.agent_id", *body.AgentID, goa.FormatUUID))
	}
	return
}
